/** Dil başına tek URL: TR /slug, diğerleri /<dil>/slug. */
export const olcuUrl = (l: GLang) => (l === 'tr' ? `/${OLCU.tr.slug}` : `/${l}/${OLCU[l].slug}`);
export const parseOlcuSlug = (l: GLang, slug: string) => OLCU[l].slug === slug;
/** 10 dil + x-default (EN). */
export const olcuLanguages = (): Record<string, string> => ({
  ...Object.fromEntries(GLANGS.map((l) => [l, `${OLCU_SITE}${olcuUrl(l)}`])),
  'x-default': `${OLCU_SITE}${olcuUrl('en')}`,
});

